class 선수:
    def __init__(self, 이름):
        self.이름 = 이름
        self.골 = 0
선수들 = [선수("민수"), 선수("지아"), 선수("하준")]
while True:
    누구 = input("골을 넣은 선수: ")
    if 누구 == "끝":
        break
    for 한명 in 선수들:
        if 한명.이름 == 누구:
            한명.골 += 1
으뜸 = 선수들[0]
for 한명 in 선수들:
    if 한명.골 > 으뜸.골:
        으뜸 = 한명
print(으뜸.이름, 으뜸.골)
